455	// ServerContext 只保留 store 的裸指针供查询；stop() 时一并清理。
456	//
457	// 与 BluetoothPlugin（monitor_plugins.cpp）的职责切分：
458	//   BluetoothPlugin  = BlueZ D-Bus 状态采集（设备列表/RSSI/连接态）
459	//   BtEventsPlugin   = 内核 eBPF 事件采集（断连原因 + 归一化事件）
460	// 两条链路共享 BT 数据域但互不调用，避免一边故障拖垮另一边。
461	// ---------------------------------------------------------------------------
462	class BtEventsPlugin : public IMonitorPlugin {
463	    ServerContext* ctx_ = nullptr;
464	    std::unique_ptr<WirelessEventStore> store_;
465	    std::unique_ptr<BtLinkQualityTracker> tracker_;
466	    std::unique_ptr<SiteIncidentCorrelator> correlator_;
467	    std::unique_ptr<BtEventMonitor> monitor_;
468	public:
469	    const char* name() const override { return "bt_events"; }
470	    int order() const override { return 10; }
471	    bool init(ServerContext* ctx) override { ctx_ = ctx; return true; }
472	    bool start(ServerContext* ctx) override {
473	        if (!ctx->cfg.bluetooth.enabled.load()) {
474	            LOG_INFO(LogModule::BLUETOOTH, "bt_events plugin disabled by config (bluetooth.enabled=false)");
475	            return true;
476	        }
477	        if (!ctx->db_mgr) {
478	            LOG_WARNING(LogModule::BLUETOOTH,
479	                        "BtEventsPlugin: db_mgr not ready — event store unavailable");
480	            return true;
481	        }
482	
483	        // 事件来源身份：gateway_id 对齐 edge.device_id（云端资产主键），
484	        // 为空时回落到 hostname，保证每条事件都能回答"是哪台探针看到的"。
485	        //
486	        // site_id 来自 edge.site_id 配置：多网关部署时同一现场的多台网关共享
487	        // 此值，云端据此聚合现场视图。留空则回落 gateway_id —— 即
488	        // "1 Gateway = 1 Site" 的历史行为完全不变。
489	        WirelessEventStoreConfig store_cfg;
490	        store_cfg.gateway_id = ctx->cfg.edge.device_id.get();
491	        if (store_cfg.gateway_id.empty()) {
492	            char hostname[256] = {0};
493	            if (gethostname(hostname, sizeof(hostname) - 1) == 0) {
494	                store_cfg.gateway_id = hostname;
495	            }
496	        }
497	        const std::string configured_site = ctx->cfg.edge.site_id.get();
498	        store_cfg.site_id = configured_site.empty() ? store_cfg.gateway_id : configured_site;
499	
500	        store_ = std::make_unique<WirelessEventStore>(ctx->db_mgr.get(), std::move(store_cfg));
501	        ctx->wireless_event_store = store_.get();
502	
503	        // Phase 2: 初始化链路质量跟踪器，并预热加载历史基线画像
504	        tracker_ = std::make_unique<BtLinkQualityTracker>();
505	        ctx->bt_link_quality_tracker = tracker_.get();
506	
507	        // Phase 3a: 区域级异常关联器——把散落的设备事件聚合成 SiteIncident。
508	        //
509	        // 构造顺序必须是 correlator → store（store 只存裸指针，无依赖），
510	        // 但**回放必须早于绑定**：
511	        //   1. 先 recoverFromStore() 恢复内存态。此时 store 尚未绑定关联器，
512	        //      回放产出的事件不会反过来被重新投递进关联器（否则每条回放事件
513	        //      都会触发一次关联，造成重复计数与无谓的 DB 写）。
514	        //   2. 再绑定。此后运行期事件才自动进入关联。
515	        //
516	        // 关联器的 site_id 与 store 一致（Phase 3a 运行模型 1 Gateway = 1 Site），
517	        // 五个阈值从配置读入——这些键是关联器的**构造期**配置，运行时改完需
518	        // `weaknet-cli monitor restart bt_events` 重建本插件才生效。
519	        SiteIncidentConfig incident_cfg;
520	        incident_cfg.site_id = store_->config().site_id;
521	        incident_cfg.min_affected_devices =
522	            ctx->cfg.bluetooth.incident_min_devices.load();
523	        incident_cfg.min_affected_ratio =
524	            ctx->cfg.bluetooth.incident_min_ratio_bp.load() / 10000.0;  // bp → 比例
525	        incident_cfg.correlation_window_ms =
526	            ctx->cfg.bluetooth.incident_window_ms.load();
527	        incident_cfg.quiet_window_ms =
528	            ctx->cfg.bluetooth.incident_quiet_window_ms.load();
529	        incident_cfg.active_device_memory_ms =
530	            ctx->cfg.bluetooth.incident_active_window_ms.load();
531	        correlator_ = std::make_unique<SiteIncidentCorrelator>(ctx->db_mgr.get(), incident_cfg);
532	        ctx->site_incident_correlator = correlator_.get();
533	
534	        // 回放窗口右沿用当前墙钟：关联器只按事件时间做决策，
535	        // 这个 now_ms 只用于确定"最近多久的事件值得回放"。
536	        const uint64_t now_ms = static_cast<uint64_t>(
537	            std::chrono::duration_cast<std::chrono::milliseconds>(
538	                std::chrono::system_clock::now().time_since_epoch()).count());
539	        correlator_->recoverFromStore(now_ms);
540	        store_->setIncidentCorrelator(correlator_.get());
541	
542	        monitor_ = std::make_unique<BtEventMonitor>(store_.get(), tracker_.get());
543	        if (!monitor_->init(ctx->cfg.bluetooth.events_bpf_obj.get(),
544	                            store_->config().gateway_id)) {
545	            LOG_WARNING(LogModule::BLUETOOTH, "BtEventsPlugin: init failed for "
546	                        << ctx->cfg.bluetooth.events_bpf_obj.get()
547	                        << " — bluetooth disconnect reason capture disabled ("
548	                        << monitor_->lastError() << ")");
549	            // 不是致命错误：事件采集失败不影响其它监控器，
550	            // 但 store 和 tracker 仍然有效（D-Bus 路径仍可产生 LinkDegraded）
551	            monitor_.reset();
552	            return true;
553	        }
554	        if (!monitor_->start()) {
555	            LOG_WARNING(LogModule::BLUETOOTH, "BtEventsPlugin: start failed: "
556	                        << monitor_->lastError());
557	            monitor_.reset();
558	            return true;
559	        }
560	
561	        LOG_INFO(LogModule::BLUETOOTH, "BtEventMonitor running, attached hooks: "
562	                 << monitor_->attachedHooksSummary());
563	        return true;
564	    }
565	    void stop() override {
566	        if (monitor_) {
567	            monitor_->stop();
568	            monitor_.reset();
569	        }
570	        // 先解绑再销毁：store 在关联器之前构造、之后销毁，
571	        // 中间任何时刻 recordEvent 都不能看到一个悬垂的关联器指针。
572	        if (store_) {
573	            store_->setIncidentCorrelator(nullptr);
574	        }
575	        if (ctx_) {
576	            if (ctx_->wireless_event_store == store_.get()) {
577	                ctx_->wireless_event_store = nullptr;
578	            }
579	            if (ctx_->bt_link_quality_tracker == tracker_.get()) {
580	                ctx_->bt_link_quality_tracker = nullptr;
581	            }
582	            if (ctx_->site_incident_correlator == correlator_.get()) {
583	                ctx_->site_incident_correlator = nullptr;
584	            }
585	        }
586	        correlator_.reset();
587	        tracker_.reset();
588	        store_.reset();
589	    }
590	};
