593	// 工业蓝牙 HCI ACL 数据通道流量监测（Phase 1 新架构，order 10）
594	// ---------------------------------------------------------------------------
595	class BtHciTrafficPlugin : public IMonitorPlugin {
596	    ServerContext* ctx_ = nullptr;
597	    std::shared_ptr<weaknet::BtHciConnectionTracker> tracker_;
598	    std::unique_ptr<BtDataPathAnalyzer> analyzer_;
599	    std::unique_ptr<BtDataPathAnomalyDetector> anomaly_detector_;
600	    std::thread worker_;
601	    std::atomic<bool> stop_{false};
602	    std::atomic<uint64_t> anomaly_seq_{0};
603	public:
604	    const char* name() const override { return "bt_hci_traffic"; }
605	    int order() const override { return 10; }
606	    bool init(ServerContext* ctx) override { ctx_ = ctx; return true; }
607	    bool start(ServerContext* ctx) override {
608	        if (!ctx->cfg.bluetooth.enabled.load()) {
609	            LOG_INFO(LogModule::BLUETOOTH, "bt_hci_traffic plugin disabled by config (bluetooth.enabled=false)");
610	            return true;
611	        }
612	
613	        tracker_ = std::make_shared<weaknet::BtHciConnectionTracker>();
614	        analyzer_ = std::make_unique<BtDataPathAnalyzer>(tracker_);
615	
616	        BtAnomalyDetectorConfig anomaly_cfg;
617	        anomaly_cfg.stall_timeout_ms = ctx->cfg.bluetooth.stall_timeout_ms.load();
618	        anomaly_cfg.stall_consecutive_windows = ctx->cfg.bluetooth.stall_consecutive_windows.load();
619	        anomaly_cfg.min_expected_bps = static_cast<double>(ctx->cfg.bluetooth.min_expected_bps.load());
620	        anomaly_cfg.degraded_consecutive_windows = ctx->cfg.bluetooth.degraded_consecutive_windows.load();
621	        anomaly_detector_ = std::make_unique<BtDataPathAnomalyDetector>(anomaly_cfg);
622	
623	        std::string bpf_path = ctx->cfg.bluetooth.hci_traffic_bpf_obj.get();
624	        if (!analyzer_->init(bpf_path, "hci0")) {
625	            LOG_WARNING(LogModule::BLUETOOTH, "BtHciTrafficPlugin: init failed for "
626	                        << bpf_path << " — falling back to offline mode ("
627	                        << analyzer_->lastError() << ")");
628	        }
629	
630	        {
631	            std::unique_lock<std::shared_mutex> lock(ctx->monitor_pointers_mutex);
632	            ctx->bt_hci_analyzer = analyzer_.get();
633	            ctx->bt_anomaly_detector = anomaly_detector_.get();
634	        }
635	
636	        stop_.store(false);
637	        worker_ = std::thread([this]() {
638	            while (!stop_.load() && ctx_ && ctx_->running.load()) {
639	                std::this_thread::sleep_for(std::chrono::seconds(2));
640	                if (stop_.load()) break;
641	
642	                // 每个采样周期先同步内核连接表：HCIGETCONNLIST 实测单次 ~1.3µs，
643	                // 每 2 秒一次对 CPU 无感。必须先于 collect/prune——Tracker 活跃集
644	                // 是死句柄清理的真值，滞后同步会让刚建立的连接被误删（丢计数）。
645	                if (tracker_) {
646	                    tracker_->syncFromKernel("hci0");
647	                }
648	
649	                if (analyzer_ && analyzer_->isAvailable()) {
650	                    auto obs = analyzer_->collectObservations();
651	                    if (!obs.empty()) {
652	                        LOG_DEBUG(LogModule::BLUETOOTH, "BtDataPathAnalyzer collected "
653	                                  << obs.size() << " observations");
654	                        const int64_t now_ms = static_cast<int64_t>(
655	                            std::chrono::duration_cast<std::chrono::milliseconds>(
656	                                std::chrono::system_clock::now().time_since_epoch()).count());
657	
658	                        if (ctx_ && ctx_->db_mgr) {
659	                            for (const auto& item : obs) {
660	                                // 仅持久化有活跃流量或已知设备的观测，避免无用全零刷库
661	                                if (item.tx_packets > 0 || item.rx_packets > 0 || item.device_id.has_value()) {
662	                                    ctx_->db_mgr->insertBtDataPathMetric(
663	                                        now_ms,
664	                                        item.controller_id,
665	                                        item.connection_handle,
666	                                        item.connection_generation,
667	                                        item.attribution_scope,
668	                                        item.device_id.value_or(""),
669	                                        item.window_ms,
670	                                        item.tx_bytes,
671	                                        item.rx_bytes,
672	                                        item.tx_packets,
673	                                        item.rx_packets,
674	                                        item.tx_throughput_bps,
675	                                        item.rx_throughput_bps,
676	                                        item.max_gap_ms
677	                                    );
678	                                }
679	                            }
680	                        }
681	
682	                        // Phase 2：运行规则驱动 L2 异常评估
683	                        if (anomaly_detector_) {
684	                            // 动态吸收最新运行时配置
685	                            BtAnomalyDetectorConfig cur_cfg;
686	                            cur_cfg.stall_timeout_ms = ctx_->cfg.bluetooth.stall_timeout_ms.load();
687	                            cur_cfg.stall_consecutive_windows = ctx_->cfg.bluetooth.stall_consecutive_windows.load();
688	                            cur_cfg.min_expected_bps = static_cast<double>(ctx_->cfg.bluetooth.min_expected_bps.load());
689	                            cur_cfg.degraded_consecutive_windows = ctx_->cfg.bluetooth.degraded_consecutive_windows.load();
690	                            anomaly_detector_->updateConfig(cur_cfg);
691	
692	                            auto anomalies = anomaly_detector_->evaluate(obs, now_ms);
693	                            for (const auto& anomaly : anomalies) {
694	                                LOG_WARNING(LogModule::BLUETOOTH, "L2 BT Anomaly detected: ["
695	                                            << anomaly.anomaly_type << "] handle=" << anomaly.connection_handle
696	                                            << " device=" << anomaly.device_address
697	                                            << " severity=" << anomaly.severity << ": "
698	                                            << anomaly.description);
699	
700	                                // 若已绑定具体设备，桥接生成一条规范化设备事件 (LinkDegraded) 注入事件存储。
701	                                // 必须赋全局唯一 event_id：device_events.event_id 是 UNIQUE 且
702	                                // INSERT OR IGNORE——留空会让第 2 条起全部撞空串被静默吞掉（板端实测）。
703	                                if (!anomaly.device_address.empty() && ctx_->wireless_event_store) {
704	                                    WirelessDeviceEvent ev;
705	                                    ev.event_id = "bt_l2_" + std::to_string(now_ms) + "_" +
706	                                                  std::to_string(++anomaly_seq_);
707	                                    ev.device_address = anomaly.device_address;
708	                                    ev.event_type = DeviceEventType::LinkDegraded;
709	                                    ev.protocol = WirelessProtocol::Bluetooth;
710	                                    ev.source = EvidenceSource::Derived;
711	                                    ev.source_detail = anomaly.anomaly_type;
712	                                    ev.suspected_cause = anomaly.description;
713	                                    ev.timestamp_ms = static_cast<uint64_t>(now_ms);
714	                                    ev.details_json = anomaly.toJson();
715	                                    ctx_->wireless_event_store->recordEvent(ev);
716	                                }
717	                            }
718	                        }
719	
720	                        // 以内核连接表（Tracker 活跃集）为真值，清理死句柄的 Map 残留。
721	                        // 断连后 BPF Map 条目不会自动消失：不清理会耗尽 64 槽位
722	                        // （新连接建项失败 → 流量漏计），并让死句柄的残留累计值
723	                        // 持续产出 controller 归因的幻影观测（板端实测）。
724	                        // 必须在 collectObservations 之后：死句柄的最终窗口增量
725	                        // 需要先被核算并落库。
726	                        if (tracker_) {
727	                            std::set<uint16_t> live_handles;
728	                            for (const auto& rec : tracker_->getActiveConnections("hci0")) {
729	                                live_handles.insert(rec.key.handle);
730	                            }
731	                            analyzer_->pruneStaleEntries(live_handles);
732	                        }
733	                    }
734	                }
735	            }
736	        });
737	
738	        LOG_INFO(LogModule::BLUETOOTH, "BtHciTrafficPlugin started successfully, hooks: "
739	                 << analyzer_->attachedHookName());
740	        return true;
741	    }
742	    void stop() override {
743	        stop_.store(true);
744	        if (worker_.joinable()) {
745	            worker_.join();
746	        }
747	        if (analyzer_) {
748	            analyzer_->stop();
749	        }
750	        if (ctx_) {
751	            std::unique_lock<std::shared_mutex> lock(ctx_->monitor_pointers_mutex);
752	            if (ctx_->bt_hci_analyzer == analyzer_.get()) {
753	                ctx_->bt_hci_analyzer = nullptr;
754	            }
755	            if (ctx_->bt_anomaly_detector == anomaly_detector_.get()) {
756	                ctx_->bt_anomaly_detector = nullptr;
757	            }
758	        }
759	        analyzer_.reset();
760	        anomaly_detector_.reset();
761	        tracker_.reset();
762	    }
763	};
764	
765	void registerEbpfPlugins() {
766	    registerPlugin("dns",             [] { return std::make_unique<DnsPlugin>(); });
767	    registerPlugin("wifi_loss",       [] { return std::make_unique<WifiLossPlugin>(); });
768	    registerPlugin("http_latency",    [] { return std::make_unique<HttpLatencyPlugin>(); });
769	    registerPlugin("process_profiler",[] { return std::make_unique<ProcessProfilerPlugin>(); });
770	    registerPlugin("tcp_retrans",     [] { return std::make_unique<TcpRetransPlugin>(); });
771	    registerPlugin("tcp_conn",        [] { return std::make_unique<TcpConnPlugin>(); });
772	    registerPlugin("skb_drop",        [] { return std::make_unique<SkbDropPlugin>(); });
773	    registerPlugin("tcp_connect",     [] { return std::make_unique<TcpConnectPlugin>(); });
774	    registerPlugin("tcp_rtt",         [] { return std::make_unique<TcpRttPlugin>(); });
775	    registerPlugin("bt_events",       [] { return std::make_unique<BtEventsPlugin>(); });
776	    registerPlugin("bt_hci_traffic",  [] { return std::make_unique<BtHciTrafficPlugin>(); });
777	}
778	
779	}  // namespace weaknet_dbus

