1074	void start_tcp_conn_monitor_thread(ServerContext* ctx, std::thread* worker, TcpConnMonitor* monitor) {
1075	    *worker = std::thread([ctx, monitor]() {
1076	        // The plugin owns this monitor; the worker borrows it until join.
1077	        if (!monitor) return;
1078	        LOG_INFO(LogModule::TCP_LOSS, "TCP conn monitor thread started");
1079	        while ((ctx->running.load() && !ctx->tcp_conn_stop.load())) {
1080	            const auto stats = monitor->getStats();
1081	            if (stats.totalAccepts > 0 || stats.totalAcceptFailures > 0) {
1082	                LOG_INFO(LogModule::TCP_LOSS, "TCP conn tick: accepts=" << stats.totalAccepts
1083	                    << " closes=" << stats.totalCloses
1084	                    << " active=" << stats.activeInbound
1085	                    << " acceptFailures=" << stats.totalAcceptFailures
1086	                    << " avgDur=" << stats.avgDurationMs << "ms");
1087	            }
1088	            for (int i = 0; i < static_cast<int>(ctx->cfg.tcp_conn.interval_ms.load() / 100) && (ctx->running.load() && !ctx->tcp_conn_stop.load()); ++i)
1089	                std::this_thread::sleep_for(100ms);
1090	        }
1091	        monitor->stop();
1092	        LOG_INFO(LogModule::TCP_LOSS, "TCP conn monitor thread stopped");
1093	    });
1094	}
