1096	// 启动历史数据持久化线程
1097	void start_tcp_connect_monitor_thread(ServerContext* ctx, std::thread* worker, TcpConnectMonitor* monitor) {
1098	    *worker = std::thread([ctx, monitor]() {
1099	        if (!monitor) return;
1100	        LOG_INFO(LogModule::NETWORK, "TCP connect monitor thread started");
1101	        // 与 DNS 捕获同构：高频排空 perf buffer，避免突发建连丢事件
1102	        while ((ctx->running.load() && !ctx->tcp_connect_stop.load())) {
1103	            monitor->drain();
1104	            std::this_thread::sleep_for(200ms);
1105	        }
1106	        monitor->stop();
1107	        LOG_INFO(LogModule::NETWORK, "TCP connect monitor thread stopped");
1108	    });
1109	}
