1123	                    << " total_samples=" << stats.totalSamples);
1124	            }
1125	            const uint32_t interval = ctx->cfg.tcp_rtt.interval_ms.load();
1126	            for (int i = 0; i < static_cast<int>(interval / 100) && (ctx->running.load() && !ctx->tcp_rtt_stop.load()); ++i) {
1127	                std::this_thread::sleep_for(100ms);
1128	            }
1129	        }
1130	        monitor->stop();
